"""Fixed emergency wording used when the safety rules fire. Written by people, not generated by the AI, so it
is always available — including when the AI provider is down or slow."""
from __future__ import annotations

EMERGENCY_REPLY = {
    "en": "This may be a medical emergency. Call 112 now or go to the nearest emergency department. Do not wait.",
    "ta": "இது மருத்துவ அவசரநிலையாக இருக்கலாம். உடனே 112-ஐ அழைக்கவும் அல்லது அருகிலுள்ள அவசர சிகிச்சைப் பிரிவுக்குச் செல்லவும். காத்திருக்க வேண்டாம்.",
    "hi": "यह मेडिकल इमरजेंसी हो सकती है। तुरंत 112 पर कॉल करें या सबसे नज़दीकी इमरजेंसी विभाग में जाएँ। इंतज़ार न करें।",
}

MENTAL_HEALTH_LINE = {
    "en": "You can also call Tele-MANAS on 14416 for free 24x7 mental-health support.",
    "ta": "இலவச 24x7 மனநல ஆதரவுக்கு Tele-MANAS 14416-ஐ அழைக்கலாம்.",
    "hi": "मुफ़्त 24x7 मानसिक स्वास्थ्य सहायता के लिए Tele-MANAS 14416 पर कॉल करें।",
}


def emergency_text(language: str, categories: tuple[str, ...] | list[str]) -> str:
    text = EMERGENCY_REPLY[language]
    if "self_harm" in categories:
        text += " " + MENTAL_HEALTH_LINE[language]
    return text
